MATCH (c:Crime)-[:INVESTIGATED_BY]->(o:Officer {surname: "Stanman"})
WHERE EXISTS {
  MATCH (c2:Crime)-[:INVESTIGATED_BY]->(o)
  WHERE c2.last_outcome = "Under investigation"
  AND EXISTS {
    MATCH (c2)<-[:PARTY_TO]-(p2:Person {surname: "George"})
  }
}
WITH DISTINCT c
RETURN count(c)

MATCH (v:Vehicle {model: "S8"})-[:INVOLVED_IN]->(c:Crime {last_outcome: "Investigation complete; no suspect identified"})-[:INVESTIGATED_BY]->(o:Officer)
WHERE EXISTS {
  MATCH (c2:Crime)-[:INVESTIGATED_BY]->(o)
  MATCH (p:Person)-[:PARTY_TO]->(c2)
}
RETURN DISTINCT v.reg

MATCH (c:Crime)-[:OCCURRED_AT]->(l:Location)
WHERE c.date = "7/08/2017" AND l.address CONTAINS "Glaister Lane"
AND (
  EXISTS { MATCH (l)-[:LOCATION_IN_AREA]->(a:Area {areaCode: "BL2"}) }
  OR EXISTS { MATCH (l)-[:HAS_POSTCODE]->(:PostCode)-[:POSTCODE_IN_AREA]->(a2:Area {areaCode: "BL2"}) }
)
RETURN c.last_outcome

MATCH (p:Person {nhs_no: "804-54-6976"})-[:KNOWS]-(friend:Person)
WHERE EXISTS {
  MATCH (other:Person)-[:KNOWS_PHONE]->(friend)
}
RETURN DISTINCT friend.nhs_no

CALL {
  MATCH (:Vehicle {make: "Mercedes-Benz"})-[:INVOLVED_IN]->(c:Crime)-[:INVESTIGATED_BY]->(o:Officer)
  RETURN o
}
WITH DISTINCT o
RETURN count(o)

MATCH (p:Person)-[:CURRENT_ADDRESS]->(:Location)
WHERE EXISTS {
  MATCH (p)-[:FAMILY_REL]->(:Person)
}
AND EXISTS {
  MATCH (p)-[:KNOWS]->(k:Person {surname: "Cooper"})-[:CURRENT_ADDRESS]->(l:Location)-[:HAS_POSTCODE]->(pc:PostCode {code: "BL5 2RN"})
}
RETURN DISTINCT p.name

MATCH (p:Person)-[:KNOWS]->(other:Person {surname: "Carr"})
MATCH (other)-[:CURRENT_ADDRESS]->(loc:Location)-[:HAS_POSTCODE]->(pc:PostCode {code: "BL1 1LE"})
MATCH (p)-[:CURRENT_ADDRESS]->(ploc:Location)
WHERE EXISTS { MATCH (p)-[:FAMILY_REL]->(:Person)-[:CURRENT_ADDRESS]->(ploc) }
   OR EXISTS { MATCH (p)<-[:FAMILY_REL]-(:Person)-[:CURRENT_ADDRESS]->(ploc) }
RETURN DISTINCT p.name
